// Parse a Netscape bookmark file (the format all browsers export/import).
// Folder names on the path become tags. Returns an array of import items.
export function parseNetscape(html) {
  const $ = cheerio.load(html);
  const items = [];
  $('a').each((_, el) => {
    const a = $(el);
    const url = a.attr('href');
    if (!url || /^(place:|javascript:)/i.test(url)) return;

    // Folder path = every <h3> that precedes this link's <dl> ancestors.
    const folders = [];
    a.parentsUntil('body', 'dl').each((_, dl) => {
      const h3 = $(dl).prevAll('h3').first().text().trim();
      if (h3) folders.push(h3);
    });

    const tagAttr = (a.attr('tags') || '').split(',').map((s) => s.trim()).filter(Boolean);
    const tags = [...new Set([...folders, ...tagAttr])];

    const addDate = a.attr('add_date');
    let created_at;
    if (addDate && /^\d+$/.test(addDate)) {
      created_at = new Date(parseInt(addDate, 10) * 1000).toISOString();
    }

    items.push({
      url,
      title: a.text().trim(),
      tags,
      created_at,
    });
  });
  return items;
}

function esc(s) {
  return String(s || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

// Generate a Netscape bookmark file from export data.
export function toNetscape(exportData) {
  const lines = [
    '<!DOCTYPE NETSCAPE-Bookmark-file-1>',
    '<META HTTP-EQUIV="Content-Type" CONTENT="text/html; charset=UTF-8">',
    '<TITLE>Bookmarks</TITLE>',
    '<H1>Bookmarks</H1>',
    '<DL><p>',
  ];
  for (const b of exportData.bookmarks) {
    const date = b.created_at ? Math.floor(new Date(b.created_at).getTime() / 1000) : '';
    const tags = (b.tags || []).join(',');
    lines.push(
      `    <DT><A HREF="${esc(b.url)}"${date ? ` ADD_DATE="${date}"` : ''}` +
        `${tags ? ` TAGS="${esc(tags)}"` : ''}>${esc(b.title || b.url)}</A>`
    );
    if (b.description) lines.push(`    <DD>${esc(b.description)}`);
  }
  lines.push('</DL><p>');
  return lines.join('\n');
}
// URL helpers: normalization for deduplication and domain extraction.

// Tracking / analytics params that should not create distinct bookmarks.
const STRIP_PARAMS = new Set([
  'utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content',
  'utm_id', 'utm_reader', 'utm_name', 'utm_social', 'utm_social-type',
  'gclid', 'fbclid', 'mc_cid', 'mc_eid', 'igshid', 'ref', 'ref_src',
  'ref_url', 'yclid', 'msclkid', '_ga', 'spm', 'scm',
]);

export function ensureProtocol(raw) {
  const trimmed = String(raw || '').trim();
  if (!trimmed) return '';
  if (/^[a-z][a-z0-9+.-]*:\/\//i.test(trimmed)) return trimmed;
  if (/^(mailto|tel):/i.test(trimmed)) return trimmed;
  return 'https://' + trimmed;
}

// Produce a canonical key used to detect duplicate URLs. Two URLs that differ
// only by protocol case, default port, trailing slash, tracking params, a
// leading "www.", or fragment collapse to the same key.
export function normalizeUrl(raw) {
  const withProto = ensureProtocol(raw);
  let u;
  try {
    u = new URL(withProto);
  } catch {
    return withProto.toLowerCase();
  }
  u.protocol = u.protocol.toLowerCase();
  u.hostname = u.hostname.toLowerCase().replace(/^www\./, '');
  u.hash = '';

  // Drop default ports.
  if ((u.protocol === 'http:' && u.port === '80') ||
      (u.protocol === 'https:' && u.port === '443')) {
    u.port = '';
  }

  // Remove tracking params, then sort the rest for stable ordering.
  const params = [...u.searchParams.entries()]
    .filter(([k]) => !STRIP_PARAMS.has(k.toLowerCase()))
    .sort((a, b) => (a[0] === b[0] ? a[1].localeCompare(b[1]) : a[0].localeCompare(b[0])));
  u.search = '';
  for (const [k, v] of params) u.searchParams.append(k, v);

  // Collapse trailing slash on the path (but keep root "/").
  let key = u.toString();
  key = key.replace(/\/(\?|$)/, '$1');
  // Treat http and https as the same resource for deduplication.
  key = key.replace(/^http:\/\//, 'https://');
  return key;
}

export function extractDomain(raw) {
  try {
    return new URL(ensureProtocol(raw)).hostname.replace(/^www\./, '');
  } catch {
    return '';
  }
}
