      <button class="btn btn-ghost" data-close>Cancel</button>
      <button class="btn btn-primary" id="p-save">Save preferences</button>
    </div>`);

  $('#p-save', overlay).onclick = async () => {
    const patch = {
      theme: $('#p-theme', overlay).value,
      view: $('#p-view', overlay).value,
      density: $('#p-density', overlay).value,
      default_sort: $('#p-sort', overlay).value,
      show_previews: $('#p-prev', overlay).checked,
    };
    state.prefs = await api.patch('/api/preferences', patch);
    applyPrefs();
    close();
    await load();
    toast('Preferences saved.', { type: 'success' });
  };
}

function applyPrefs() {
  const p = state.prefs;
  state.theme = p.theme; state.view = p.view; state.density = p.density; state.showPreviews = p.show_previews;
  document.documentElement.setAttribute('data-theme', p.theme || 'auto');
  $$('#view-toggle button').forEach((b) => b.classList.toggle('active', b.dataset.view === state.view));
  if (!state.sortTouched) { state.sort = p.default_sort || 'created_desc'; $('#sort').value = state.sort; }
}

// ---- Import / export modal ------------------------------------------------

function openIoModal() {
  const { overlay, close } = openModal(`
    <div class="modal-head"><h2>Import / Export</h2><button class="close-x">×</button></div>
    <div class="modal-body">
      <div class="field">
        <label>Export</label>
        <span class="hint">Download all bookmarks (and saved filters).</span>
        <div style="display:flex;gap:10px;margin-top:6px;">
          <a class="btn" href="/api/export.json" download>⬇ JSON (full)</a>
          <a class="btn" href="/api/export.html" download>⬇ Browser HTML</a>
        </div>
      </div>
      <div class="field">
        <label>Import</label>
        <span class="hint">Select a JSON export or a browser bookmarks HTML file. Duplicates are skipped.</span>
        <input type="file" id="import-file" accept=".json,.html,.htm,application/json,text/html" style="margin-top:6px;" />
      </div>
    </div>
    <div class="modal-foot">
      <button class="btn btn-ghost" data-close>Close</button>
      <button class="btn btn-primary" id="import-btn">Import file</button>
    </div>`, { wide: false });

  $('#import-btn', overlay).onclick = async () => {
    const file = $('#import-file', overlay).files[0];
    if (!file) { toast('Choose a file first.', { type: 'error' }); return; }
    const text = await file.text();
    const isHtml = /\.html?$/i.test(file.name) || /<a\s/i.test(text.slice(0, 4000));
    try {
      let result;
      if (isHtml) {
        const r = await fetch('/api/import', { method: 'POST', headers: { 'Content-Type': 'text/html' }, body: text });
        if (!r.ok) throw new Error('server rejected the file');
        result = await r.json();
      } else {
        result = await api.post('/api/import', JSON.parse(text));
      }
      close();
      toast(`Imported ${result.imported}, skipped ${result.skipped} duplicate(s).`, { type: 'success', timeout: 6000 });
      await Promise.all([load(), renderSidebar()]);
    } catch (e) {
      toast('Import failed: ' + (e.message || 'invalid file'), { type: 'error' });
    }
  };
}

// ---- Bulk / tag prompts ---------------------------------------------------

async function runBulk(action) {
  const ids = [...state.selected];
  if (!ids.length) return;
  let value;
  if (action === 'add_tag' || action === 'remove_tag') {
    value = prompt(action === 'add_tag' ? 'Tag(s) to add (comma separated):' : 'Tag(s) to remove (comma separated):');
    if (!value) return;
  }
  if (action === 'delete' && !confirm(`Delete ${ids.length} bookmark(s) permanently?`)) return;
  const res = await api.post('/api/bulk', { ids, action, value });
  if (action === 'delete') state.selected.clear();
  toast(`Updated ${res.affected} bookmark(s).`, { type: 'success' });
  await Promise.all([load(), renderSidebar()]);
}

// ---- Saved filters --------------------------------------------------------

function openSaveFilterModal() {
  const { overlay, close } = openModal(`
    <div class="modal-head"><h2>Save current filter</h2><button class="close-x">×</button></div>
    <div class="modal-body">
      <div class="field">
        <label>Name</label>
        <input type="text" id="filter-name" placeholder="e.g. Design reading" autofocus />
      </div>
      <div class="field">
        <span class="hint">Query: <code>${esc(state.query || '(none)')}</code> · Scope: ${esc(state.scope)} · Sort: ${esc(state.sort)}</span>
      </div>
    </div>
    <div class="modal-foot">
      <button class="btn btn-ghost" data-close>Cancel</button>
      <button class="btn btn-primary" id="save-filter">Save filter</button>
    </div>`);
  $('#save-filter', overlay).onclick = async () => {
    const name = $('#filter-name', overlay).value.trim();
    if (!name) { toast('Name the filter first.', { type: 'error' }); return; }
    await api.post('/api/filters', { name, query: state.query, scope: state.scope, sort: state.sort });
    close();
    toast('Filter saved.', { type: 'success' });
    renderSidebar();
  };
}

function applySavedFilter(f) {
  state.query = f.query; state.scope = f.scope; state.sort = f.sort; state.sortTouched = true;
  $('#search').value = f.query;
  $('#sort').value = f.sort;
  setActiveScope();
  load();
}

// ---- Scope nav ------------------------------------------------------------

function setActiveScope() {
  $$('#scope-nav .nav-item').forEach((b) => b.classList.toggle('active', b.dataset.scope === state.scope));
}

// ---- Event wiring ---------------------------------------------------------

function wire() {
  $('#add-btn').onclick = () => openAddModal();
  $('#prefs-btn').onclick = openPrefsModal;
  $('#io-btn').onclick = openIoModal;
  $('#save-filter-btn').onclick = openSaveFilterModal;

  const doSearch = debounce(() => { state.query = $('#search').value.trim(); load(); }, 250);
  $('#search').addEventListener('input', doSearch);

  $('#sort').addEventListener('change', () => { state.sort = $('#sort').value; state.sortTouched = true; load(); });

  $('#view-toggle').addEventListener('click', (e) => {
    const btn = e.target.closest('button'); if (!btn) return;
    state.view = btn.dataset.view;
    $$('#view-toggle button').forEach((b) => b.classList.toggle('active', b === btn));
    render();
  });

  $('#scope-nav').addEventListener('click', (e) => {
    const item = e.target.closest('.nav-item'); if (!item) return;
    state.scope = item.dataset.scope;
    setActiveScope();
    load();
  });

  // Delegate card interactions.
  $('#cards').addEventListener('click', async (e) => {
    const tagEl = e.target.closest('[data-tag]');
    if (tagEl) { applyTagSearch(tagEl.dataset.tag); return; }

    const selBox = e.target.closest('[data-select]');
    if (selBox) {
      const id = Number(selBox.dataset.select);
      if (selBox.checked) state.selected.add(id); else state.selected.delete(id);
      e.target.closest('.card').classList.toggle('selected', selBox.checked);
      updateBulkBar();
      $('#select-all').checked = state.bookmarks.every((b) => state.selected.has(b.id));
      return;
    }

    const actBtn = e.target.closest('[data-act]');
    if (actBtn) {
      const id = Number(actBtn.dataset.id);
      const act = actBtn.dataset.act;
      const bm = state.bookmarks.find((b) => b.id === id);
      if (act === 'edit') { openEditModal(id); return; }
      if (act === 'read_later') await api.patch(`/api/bookmarks/${id}`, { read_later: !bm.read_later });
      if (act === 'archive') {
        await api.patch(`/api/bookmarks/${id}`, { archived: !bm.archived });
        toast(bm.archived ? 'Unarchived.' : 'Archived.', {
          type: 'success', action: 'Undo',
          onAction: async () => { await api.patch(`/api/bookmarks/${id}`, { archived: bm.archived }); load(); },
        });
      }
      await load();
      return;
    }
  });

  $('#select-all').addEventListener('change', (e) => {
    if (e.target.checked) state.bookmarks.forEach((b) => state.selected.add(b.id));
    else state.bookmarks.forEach((b) => state.selected.delete(b.id));
    render();
  });

  $('#bulk-bar').addEventListener('click', (e) => {
    const btn = e.target.closest('[data-bulk]'); if (!btn) return;
    runBulk(btn.dataset.bulk);
  });
  $('#bulk-clear').onclick = () => { state.selected.clear(); render(); };

  // Sidebar: tags + saved filters (delegated).
  $('#tag-cloud').addEventListener('click', (e) => {
    const chip = e.target.closest('[data-tag]');
    if (chip) applyTagSearch(chip.dataset.tag);
  });
  $('#saved-filters').addEventListener('click', (e) => {
    const del = e.target.closest('[data-del-filter]');
    if (del) { api.del(`/api/filters/${del.dataset.delFilter}`).then(renderSidebar); return; }
    const row = e.target.closest('.saved-filter');
    if (row) applySavedFilter(JSON.parse(row.dataset.filter));
  });

  // Keyboard: press "n" to add, "/" to focus search.
  document.addEventListener('keydown', (e) => {
    if (e.target.matches('input, textarea, select')) return;
    if (e.key === '/') { e.preventDefault(); $('#search').focus(); }
    if (e.key === 'n') { e.preventDefault(); openAddModal(); }
  });
}

function applyTagSearch(tag) {
  const token = /\s/.test(tag) ? `tag:"${tag}"` : `tag:${tag}`;
  const cur = $('#search').value.trim();
  if (cur.includes(token)) return;
  $('#search').value = (cur ? cur + ' ' : '') + token;
  state.query = $('#search').value.trim();
  load();
}

// ---- Boot -----------------------------------------------------------------

async function boot() {
  wire();
  try {
    state.prefs = await api.get('/api/preferences');
  } catch { state.prefs = { theme: 'auto', view: 'grid', density: 'comfortable', show_previews: true, default_sort: 'created_desc' }; }
  applyPrefs();
  setActiveScope();
  await Promise.all([load(), renderSidebar()]);
  document.getElementById('app').setAttribute('data-harness-ready', 'true');
}

boot();
/* ---- Design tokens ------------------------------------------------------- */
:root {
  --font: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --radius: 12px;
  --radius-sm: 8px;
  --maxw: 1200px;

  --bg: #f6f7f9;
  --surface: #ffffff;
  --surface-2: #f0f2f5;
  --border: #e2e5ea;
  --border-strong: #cfd4dc;
  --text: #1a1d24;
  --text-2: #565d6b;
  --text-3: #8a92a1;
  --accent: #3b5bfd;
  --accent-weak: #eaeeff;
  --danger: #d64545;
  --danger-weak: #fdeaea;
  --shadow: 0 1px 2px rgba(20, 24, 40, 0.06), 0 4px 16px rgba(20, 24, 40, 0.06);
  --shadow-lg: 0 12px 40px rgba(20, 24, 40, 0.18);
}

:root[data-theme="dark"] {
  --bg: #0f1115;
  --surface: #181b22;
  --surface-2: #21252e;
  --border: #2a2f3a;
  --border-strong: #3a414f;
  --text: #eceef2;
  --text-2: #a9b1bf;
  --text-3: #6f7889;
  --accent: #6f86ff;
  --accent-weak: #1e243b;
  --danger: #f26d6d;
  --danger-weak: #35211f;
  --shadow: 0 1px 2px rgba(0, 0, 0, 0.3), 0 6px 20px rgba(0, 0, 0, 0.35);
  --shadow-lg: 0 16px 48px rgba(0, 0, 0, 0.55);
}

@media (prefers-color-scheme: dark) {
  :root[data-theme="auto"] {
    --bg: #0f1115; --surface: #181b22; --surface-2: #21252e;
    --border: #2a2f3a; --border-strong: #3a414f;
    --text: #eceef2; --text-2: #a9b1bf; --text-3: #6f7889;
    --accent: #6f86ff; --accent-weak: #1e243b;
    --danger: #f26d6d; --danger-weak: #35211f;
    --shadow: 0 1px 2px rgba(0,0,0,.3), 0 6px 20px rgba(0,0,0,.35);
    --shadow-lg: 0 16px 48px rgba(0,0,0,.55);
  }
}

* { box-sizing: border-box; }
html, body { height: 100%; }
body {
  margin: 0;
  font-family: var(--font);
  background: var(--bg);
  color: var(--text);
  font-size: 15px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}
button { font-family: inherit; cursor: pointer; }
a { color: var(--accent); text-decoration: none; }
a:hover { text-decoration: underline; }

/* ---- Layout -------------------------------------------------------------- */
.app { display: grid; grid-template-columns: 260px 1fr; min-height: 100vh; }

.sidebar {
  background: var(--surface);
  border-right: 1px solid var(--border);
  padding: 20px 16px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  position: sticky;
  top: 0;
  height: 100vh;
  overflow-y: auto;
}
.brand { display: flex; align-items: center; gap: 10px; font-weight: 700; font-size: 18px; }
.brand-mark { color: var(--accent); }

.add-btn { width: 100%; justify-content: center; font-weight: 600; }
.plus { font-size: 18px; line-height: 1; }

.nav { display: flex; flex-direction: column; gap: 2px; }
.nav-item {
  display: flex; justify-content: space-between; align-items: center;
  background: none; border: none; color: var(--text-2);
  padding: 9px 12px; border-radius: var(--radius-sm); font-size: 14px;
  font-weight: 500; text-align: left;
}
.nav-item:hover { background: var(--surface-2); color: var(--text); }
.nav-item.active { background: var(--accent-weak); color: var(--accent); }
.nav-count {
  font-size: 12px; color: var(--text-3);
  background: var(--surface-2); padding: 1px 8px; border-radius: 20px; font-weight: 600;
}
.nav-item.active .nav-count { background: var(--surface); color: var(--accent); }

.nav-section-head {
  font-size: 11px; text-transform: uppercase; letter-spacing: .06em;
  color: var(--text-3); font-weight: 700; margin: 0 8px 8px; padding-top: 4px;
}
.saved-filters, .tag-cloud { display: flex; flex-direction: column; gap: 2px; }
.saved-filter {
  display: flex; justify-content: space-between; align-items: center;
  padding: 7px 12px; border-radius: var(--radius-sm); font-size: 13px; color: var(--text-2);
}
.saved-filter:hover { background: var(--surface-2); }
.saved-filter span:first-child { cursor: pointer; flex: 1; }
.saved-filter .del { opacity: 0; border: none; background: none; color: var(--text-3); font-size: 14px; }
.saved-filter:hover .del { opacity: 1; }
.saved-filter .del:hover { color: var(--danger); }

.tag-cloud { flex-direction: row; flex-wrap: wrap; gap: 6px; padding: 0 4px; }
.tag-chip {
  font-size: 12px; padding: 3px 10px; border-radius: 20px;
  background: var(--surface-2); color: var(--text-2); border: 1px solid transparent;
}
.tag-chip:hover { border-color: var(--border-strong); color: var(--text); }
.tag-chip .c { color: var(--text-3); margin-left: 5px; }

.sidebar-footer { margin-top: auto; display: flex; flex-direction: column; gap: 4px; padding-top: 8px; border-top: 1px solid var(--border); }
.link-btn { background: none; border: none; color: var(--text-2); text-align: left; padding: 8px 12px; border-radius: var(--radius-sm); font-size: 13px; }
.link-btn:hover { background: var(--surface-2); color: var(--text); }

/* ---- Main --------------------------------------------------------------- */
.main { padding: 24px 32px 64px; max-width: var(--maxw); width: 100%; }

.topbar { display: flex; gap: 16px; align-items: center; margin-bottom: 18px; flex-wrap: wrap; }
.search-wrap { flex: 1; min-width: 280px; position: relative; display: flex; align-items: center; }
.search {
  flex: 1; padding: 11px 90px 11px 16px; border-radius: var(--radius);
  border: 1px solid var(--border); background: var(--surface); color: var(--text);
  font-size: 14px; box-shadow: var(--shadow);
}
.search:focus { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-weak); }
.ghost-btn {
  background: none; border: none; color: var(--text-2); font-size: 13px; font-weight: 500;
  padding: 6px 10px; border-radius: var(--radius-sm);
}
.ghost-btn:hover { background: var(--surface-2); color: var(--text); }
#save-filter-btn { position: absolute; right: 6px; }

.toolbar { display: flex; align-items: center; gap: 12px; }
.sort-label { font-size: 13px; color: var(--text-3); display: flex; align-items: center; gap: 6px; }
select {
  font-family: inherit; font-size: 13px; padding: 8px 10px; border-radius: var(--radius-sm);
  border: 1px solid var(--border); background: var(--surface); color: var(--text);
}
.view-toggle { display: flex; border: 1px solid var(--border); border-radius: var(--radius-sm); overflow: hidden; }
.view-toggle button { background: var(--surface); border: none; padding: 8px 12px; color: var(--text-3); font-size: 15px; }
.view-toggle button.active { background: var(--accent-weak); color: var(--accent); }

.result-meta { display: flex; align-items: center; gap: 16px; margin-bottom: 14px; }
.select-all-wrap { font-size: 13px; color: var(--text-2); display: flex; align-items: center; gap: 7px; }
.muted { color: var(--text-3); font-size: 13px; }

/* ---- Bulk bar ----------------------------------------------------------- */
.bulk-bar {
  display: flex; align-items: center; gap: 14px; flex-wrap: wrap;
  background: var(--surface); border: 1px solid var(--border-strong);
  border-radius: var(--radius); padding: 10px 16px; margin-bottom: 14px; box-shadow: var(--shadow);
}
.bulk-count { font-weight: 600; font-size: 13px; }
.bulk-actions { display: flex; gap: 6px; flex-wrap: wrap; }
.bulk-actions button {
  background: var(--surface-2); border: 1px solid var(--border); color: var(--text-2);
  padding: 6px 12px; border-radius: var(--radius-sm); font-size: 13px; font-weight: 500;
}
.bulk-actions button:hover { background: var(--accent-weak); color: var(--accent); border-color: var(--accent); }
.bulk-actions button.danger:hover { background: var(--danger-weak); color: var(--danger); border-color: var(--danger); }
#bulk-clear { margin-left: auto; }

/* ---- Cards -------------------------------------------------------------- */
.cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 18px; }
.cards.list { grid-template-columns: 1fr; gap: 10px; }

.card {
  background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius);
  overflow: hidden; display: flex; flex-direction: column; box-shadow: var(--shadow);
  transition: transform .12s ease, box-shadow .12s ease, border-color .12s ease; position: relative;
}
.card:hover { transform: translateY(-2px); box-shadow: var(--shadow-lg); border-color: var(--border-strong); }
.card.selected { border-color: var(--accent); box-shadow: 0 0 0 2px var(--accent-weak); }

.card-select { position: absolute; top: 12px; left: 12px; z-index: 2; }
.card-select input { width: 17px; height: 17px; cursor: pointer; accent-color: var(--accent); }

.card-preview {
  aspect-ratio: 16 / 9; background: var(--surface-2); display: block;
  object-fit: cover; width: 100%; border-bottom: 1px solid var(--border);
}
.card-preview.placeholder {
  display: flex; align-items: center; justify-content: center; color: var(--text-3);
  font-size: 32px; font-weight: 700;
}

.card-body { padding: 14px 16px 16px; display: flex; flex-direction: column; gap: 8px; flex: 1; }
.card-site { display: flex; align-items: center; gap: 7px; font-size: 12px; color: var(--text-3); }
.card-favicon { width: 16px; height: 16px; border-radius: 4px; object-fit: cover; flex-shrink: 0; }
.card-title { font-weight: 600; font-size: 15.5px; line-height: 1.35; color: var(--text); }
.card-title a { color: inherit; }
.card-desc { font-size: 13.5px; color: var(--text-2); display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }

.card-tags { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 2px; }
.card-tag { font-size: 11.5px; background: var(--surface-2); color: var(--text-2); padding: 2px 9px; border-radius: 20px; cursor: pointer; }
.card-tag:hover { background: var(--accent-weak); color: var(--accent); }

.card-note { font-size: 12.5px; color: var(--text-2); background: var(--surface-2); padding: 8px 10px; border-radius: var(--radius-sm); border-left: 3px solid var(--accent); }

.card-foot { display: flex; align-items: center; gap: 4px; margin-top: auto; padding-top: 6px; }
.card-badges { display: flex; gap: 6px; flex-wrap: wrap; margin-right: auto; }
.badge { font-size: 11px; font-weight: 600; padding: 2px 8px; border-radius: 20px; }
.badge.read { background: var(--accent-weak); color: var(--accent); }
.badge.snap { background: var(--surface-2); color: var(--text-2); }
.icon-btn {
  border: none; background: none; color: var(--text-3); font-size: 15px; padding: 6px;
  border-radius: var(--radius-sm); line-height: 1;
}
.icon-btn:hover { background: var(--surface-2); color: var(--text); }
.icon-btn.on { color: var(--accent); }

/* list view tweaks */
.cards.list .card { flex-direction: row; align-items: stretch; }
.cards.list .card-preview { width: 160px; aspect-ratio: auto; border-bottom: none; border-right: 1px solid var(--border); flex-shrink: 0; }
.cards.list .card-preview.placeholder { font-size: 24px; }
.cards.list .card-body { flex: 1; }
.compact .card-desc { -webkit-line-clamp: 2; }
.compact .card-preview { aspect-ratio: 21 / 9; }

/* ---- Empty state -------------------------------------------------------- */
.empty { text-align: center; padding: 80px 20px; color: var(--text-3); }
.empty h3 { color: var(--text-2); font-weight: 600; margin: 0 0 8px; }

/* ---- Buttons ------------------------------------------------------------ */
.btn {
  display: inline-flex; align-items: center; gap: 8px; border: 1px solid var(--border);
  background: var(--surface); color: var(--text); padding: 10px 16px; border-radius: var(--radius-sm);
  font-size: 14px; font-weight: 500;
}
.btn:hover { background: var(--surface-2); }
.btn-primary { background: var(--accent); border-color: var(--accent); color: #fff; }
.btn-primary:hover { background: var(--accent); filter: brightness(1.07); }
.btn-danger { background: var(--danger); border-color: var(--danger); color: #fff; }
.btn-ghost { background: none; }

/* ---- Modal -------------------------------------------------------------- */
.overlay {
  position: fixed; inset: 0; background: rgba(15, 17, 21, 0.5);
  display: flex; align-items: flex-start; justify-content: center;
  padding: 48px 16px; z-index: 100; overflow-y: auto; backdrop-filter: blur(2px);
}
.modal {
  background: var(--surface); border-radius: var(--radius); width: 100%; max-width: 620px;
  box-shadow: var(--shadow-lg); border: 1px solid var(--border); animation: pop .14s ease;
}
.modal.wide { max-width: 820px; }
@keyframes pop { from { transform: scale(.97); opacity: 0; } to { transform: scale(1); opacity: 1; } }
.modal-head { display: flex; align-items: center; justify-content: space-between; padding: 18px 22px; border-bottom: 1px solid var(--border); }
.modal-head h2 { margin: 0; font-size: 17px; }
.modal-body { padding: 22px; display: flex; flex-direction: column; gap: 16px; }
.modal-foot { padding: 16px 22px; border-top: 1px solid var(--border); display: flex; justify-content: flex-end; gap: 10px; align-items: center; }
.close-x { border: none; background: none; font-size: 22px; color: var(--text-3); line-height: 1; }
.close-x:hover { color: var(--text); }

.field { display: flex; flex-direction: column; gap: 6px; }
.field label { font-size: 13px; font-weight: 600; color: var(--text-2); }
.field input[type="text"], .field input[type="url"], .field textarea, .field select {
  padding: 10px 12px; border: 1px solid var(--border); border-radius: var(--radius-sm);
  background: var(--surface); color: var(--text); font-size: 14px; font-family: inherit; width: 100%;
}
.field input:focus, .field textarea:focus, .field select:focus { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-weak); }
.field textarea { resize: vertical; min-height: 70px; }
.field .hint { font-size: 12px; color: var(--text-3); }
.row-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.check-row { display: flex; gap: 20px; align-items: center; }
.check-row label { display: flex; align-items: center; gap: 8px; font-weight: 500; color: var(--text); font-size: 14px; }

.meta-preview { display: flex; gap: 14px; padding: 14px; background: var(--surface-2); border-radius: var(--radius-sm); }
.meta-preview img { width: 120px; height: 68px; object-fit: cover; border-radius: 6px; background: var(--bg); flex-shrink: 0; }
.meta-preview .mp-body { min-width: 0; }
.meta-preview .mp-title { font-weight: 600; font-size: 14px; }
.meta-preview .mp-desc { font-size: 12.5px; color: var(--text-2); margin-top: 4px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }

.spinner { width: 15px; height: 15px; border: 2px solid var(--border-strong); border-top-color: var(--accent); border-radius: 50%; animation: spin .7s linear infinite; display: inline-block; }
@keyframes spin { to { transform: rotate(360deg); } }

/* snapshots */
.snap-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 12px; }
.snap-item { border: 1px solid var(--border); border-radius: var(--radius-sm); overflow: hidden; }
.snap-item img { width: 100%; height: 110px; object-fit: cover; object-position: top; display: block; background: var(--surface-2); }
.snap-meta { padding: 8px 10px; font-size: 11.5px; color: var(--text-3); display: flex; justify-content: space-between; align-items: center; gap: 6px; }
.snap-meta a { font-size: 11.5px; }

/* ---- Toasts ------------------------------------------------------------- */
.toasts { position: fixed; bottom: 24px; right: 24px; display: flex; flex-direction: column; gap: 10px; z-index: 200; }
.toast {
  background: var(--surface); border: 1px solid var(--border-strong); border-radius: var(--radius-sm);
  padding: 12px 16px; box-shadow: var(--shadow-lg); font-size: 13.5px; color: var(--text);
  display: flex; align-items: center; gap: 12px; min-width: 260px; animation: slidein .2s ease;
}
.toast.error { border-left: 3px solid var(--danger); }
.toast.success { border-left: 3px solid var(--accent); }
.toast .toast-action { margin-left: auto; color: var(--accent); font-weight: 600; background: none; border: none; font-size: 13px; }
@keyframes slidein { from { transform: translateX(20px); opacity: 0; } to { transform: translateX(0); opacity: 1; } }

.hidden { display: none !important; }

/* ---- Responsive --------------------------------------------------------- */
@media (max-width: 820px) {
  .app { grid-template-columns: 1fr; }
  .sidebar { position: static; height: auto; flex-direction: column; }
  .main { padding: 20px 16px 48px; }
  .cards.list .card-preview { width: 96px; }
}
